// Re-validates what Angular already checked. Checklist requirement: input from
// the frontend is validated again in the workflow so a crafted request cannot
// reach the paid model.
const b = $input.first().json.body || {};
const CUISINES = ['german','italian','indian','japanese','gourmet','fusion'];
const DIETS = ['vegetarian','vegan','keto','no-preference'];
const TIMES = ['quick','medium','complex'];
const UNITS = ['gram','ml','piece'];

const errors = [];
const ing = Array.isArray(b.ingredients) ? b.ingredients : null;
if (!ing || ing.length < 1) errors.push('at least one ingredient is required');
if (ing && ing.length > 20) errors.push('at most 20 ingredients');
if (ing) for (const i of ing) {
  if (!i || typeof i.name !== 'string' || !i.name.trim()) errors.push('ingredient without a name');
  else if (i.name.length > 60) errors.push(`ingredient name too long: ${i.name.slice(0,20)}`);
  if (!(Number(i.amount) > 0) || Number(i.amount) > 9999) errors.push(`bad amount for ${i.name}`);
  if (!UNITS.includes(i.unit)) errors.push(`bad unit for ${i.name}`);
}
const portions = Number(b.portions), helpers = Number(b.helpers);
if (!Number.isInteger(portions) || portions < 1 || portions > 12) errors.push('portions must be 1-12');
if (!Number.isInteger(helpers) || helpers < 1 || helpers > 3) errors.push('helpers must be 1-3');
if (!TIMES.includes(b.cookingTime)) errors.push('cookingTime must be quick, medium or complex');
if (!CUISINES.includes(b.cuisine)) errors.push('unknown cuisine');
if (!DIETS.includes(b.diet)) errors.push('unknown diet');

return [{ json: { valid: errors.length === 0, errors, request: b } }];

// Same IP logic as the quota lookup workflow. N8N_PROXY_HOPS=1 puts the real
// visitor address into x-forwarded-for. A private or missing address means
// detection is broken, so the request counts against the system-wide cap
// instead of letting the per-IP limit become unlimited. The address itself is
// never stored: the next node turns it into a keyed hash (HMAC).
const headers = $('POST /generate-recipe (from Angular app)').first().json.headers || {};
const raw = (headers['x-forwarded-for'] || '').split(',')[0].trim();
const isPrivate = (ip) => !ip || ip.startsWith('10.') || ip.startsWith('192.168.') ||
  ip === '::1' || ip === '127.0.0.1' ||
  /^172\.(1[6-9]|2[0-9]|3[01])\./.test(ip) || /^f[cd]/i.test(ip);
const usable = !isPrivate(raw);
const date = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Berlin' });
return [{ json: { ip: raw, ipUsable: usable, date,
                  request: $('Validate request').first().json.request } }];

// Cost airbag: 3 generations per IP per day, 12 system-wide. Checked before the
// model is called, because the paid call is what needs protecting.
const PER_IP = 3, SYSTEM = 12;
const counters = $input.first().json.body || {};
const meta = $('Hash client IP').first().json;
// Per-IP counters are keyed by the HMAC of the address, never the address itself.
const ipKey = meta.ipUsable ? meta.ipHash : 'unknown';
const total = Number(counters._total || 0);
const used = meta.ipUsable ? Number(counters[ipKey] || 0) : total;
const systemLimitReached = total >= SYSTEM;
const remaining = Math.max(0, Math.min(PER_IP - used, SYSTEM - total));
return [{ json: { allowed: remaining > 0, remaining, limit: PER_IP,
                  systemLimitReached, used, total, ...meta, ipKey } }];

// Builds the instruction. The cardinality rules are repeated here on purpose:
// the API only promises syntactically valid JSON, never that a schema's
// minItems is honoured. The Parse node is what actually enforces them.
const q = $input.first().json;
const r = q.request;
const required = Math.min(Math.ceil(r.ingredients.length * 0.7), 8);
const list = r.ingredients.map(i => `${i.amount} ${i.unit} ${i.name}`).join(', ');

const prompt = `You plan recipes from ingredients someone already has at home. Your job is to reduce food waste: build meals around what is listed.

Answer with JSON only. No prose, no markdown, no code fences.

Return an object with a "recipes" array. Hard rules - a reply that breaks any of them is useless:
1. EXACTLY three recipes. Not two, not four.
2. The three must differ in preparation method or flavour direction, not just in name.
3. EACH recipe must use at least ${required} of the listed ingredients (70 percent, capped at 8 so long lists do not turn into stews).
4. Each recipe may need AT MOST three extra ingredients, and only pantry staples.
5. Respect the diet without exception. Vegetarian: no meat, no fish. Vegan: additionally no dairy, egg or honey. Keto: very low carbohydrate, no pasta, rice, potatoes or sugar.
6. Scale every amount to ${r.portions} portions.
7. Stay inside the time bracket "${r.cookingTime}": quick is up to 20 minutes, medium 20-45, complex 45 or more. cookingTimeMinutes must match.
8. Cook in ${r.cuisine} style with the spices and techniques typical for it.
9. Steps in the order they are carried out, one action per step, written for a beginner. Give each step a short title (two to four words, e.g. "Chop the onions") plus the full instruction text.
10. Use waiting times: a step done while something simmers or bakes gets parallel: true.
11. Split the work across ${r.helpers} cook(s) using assignedTo, 1-based. With one cook everything is assignedTo 1. When there is more than one cook, give each cook ONE fixed, named area of the dish that they own from start to finish - e.g. cook 2 makes the sauce from start to finish, cook 1 handles the pasta including draining it. Never move a single area’s remaining steps to a different cook partway through, even if steps for different areas interleave chronologically. Name each area in responsibilities, one short 1-3 word label per cook (index 0 = cook 1), e.g. ["pasta", "sauce"]; with one cook, responsibilities is ["everything"].
12. Estimate nutrition per portion, not per recipe. Also estimate the cooked weight of a single portion in grams (portionWeightG) - the plated weight after cooking, not the raw ingredient weight.
13. Write every piece of text in English - the title, every ingredient name, every step - no matter what language the ingredient list below is in.

Each recipe object has exactly these fields:
  title (string)
  cuisine (string, "${r.cuisine}")
  diet (string, "${r.diet}")
  timeCategory (string, "${r.cookingTime}")
  cookingTimeMinutes (integer)
  portions (integer, ${r.portions})
  helpers (integer, ${r.helpers})
  ingredientsUsed (array of {name, amount, unit})
  ingredientsMissing (array of {name, amount, unit}, at most 3)
  steps (array of {number, title, text, parallel, assignedTo})
  responsibilities (array of strings, one per cook, e.g. ["pasta", "sauce"])
  nutrition ({caloriesPerPortion, proteinG, carbsG, fatG, portionWeightG})

unit is one of: gram, ml, piece.

Ingredients available: ${list}
Portions: ${r.portions}
Cooks helping: ${r.helpers}
Time bracket: ${r.cookingTime}
Cooking style: ${r.cuisine}
Diet: ${r.diet}`;

return [{ json: { prompt } }];

// Parses the model's text answer and enforces everything the schema cannot.
// Throwing here sends the item to the error output: the first failure asks the
// model once more ('Retry Gemini once?'), the second answers the webhook with a 500 and
// fails the run in 'Fail run → error workflow emails admin', so a bad generation is reported by mail
// instead of landing in the public library or leaving the visitor waiting.
// No colons in the error messages: the Code node's task runner splits a thrown
// message at ':' and keeps only the last part.
const q = $('Check quota').first().json;
const r = q.request;
const text = $input.first().json?.content?.parts?.[0]?.text ?? '';
const cleaned = text.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();

let parsed;
try { parsed = JSON.parse(cleaned); }
catch (e) { throw new Error(`Model did not return parsable JSON (${e.message}), the full reply is in the Generate recipes output of this execution`); }

const recipes = parsed.recipes;
if (!Array.isArray(recipes)) throw new Error('No recipes array in the reply');
if (recipes.length !== 3) throw new Error(`Expected exactly 3 recipes, got ${recipes.length}`);

const UNITS = ['gram','ml','piece'];
const BRACKET = { quick: [1,20], medium: [20,45], complex: [45,600] };
const createdAt = Date.now();

const cleanIng = (arr, where) => {
  if (!Array.isArray(arr)) throw new Error(`${where} is not an array`);
  return arr.map(i => {
    if (!i || typeof i.name !== 'string' || !i.name.trim()) throw new Error(`${where} - ingredient without a name`);
    if (!UNITS.includes(i.unit)) throw new Error(`${where} - bad unit ${i.unit} for ${i.name}`);
    const amount = Number(i.amount);
    if (!(amount > 0)) throw new Error(`${where} - bad amount for ${i.name}`);
    return { name: i.name.trim(), amount, unit: i.unit };
  });
};

return recipes.map((rec, idx) => {
  const where = `recipe ${idx + 1}`;
  if (typeof rec.title !== 'string' || !rec.title.trim()) throw new Error(`${where} - missing title`);
  if (rec.cuisine !== r.cuisine) throw new Error(`${where} - cuisine ${rec.cuisine} does not match requested ${r.cuisine}`);
  if (rec.diet !== r.diet) throw new Error(`${where} - diet ${rec.diet} does not match requested ${r.diet}`);
  if (rec.timeCategory !== r.cookingTime) throw new Error(`${where} - timeCategory ${rec.timeCategory} does not match requested ${r.cookingTime}`);

  const minutes = Number(rec.cookingTimeMinutes);
  const [lo, hi] = BRACKET[r.cookingTime];
  if (!(minutes >= lo && minutes <= hi)) throw new Error(`${where} - ${minutes} min is outside bracket ${r.cookingTime}`);

  const used = cleanIng(rec.ingredientsUsed, `${where} ingredientsUsed`);
  const missing = cleanIng(rec.ingredientsMissing ?? [], `${where} ingredientsMissing`);

  // US7: each suggestion has to use at least 70 percent of the ingredients the
  // user listed, capped at 8. Matched against the request by normalised name -
  // counting the array alone would accept invented ingredients.
  const norm = (s) => s.trim().toLowerCase();
  const wanted = new Set(r.ingredients.map(i => norm(i.name)));
  const hits = new Set(used.map(i => norm(i.name)).filter(n => wanted.has(n)));
  const required = Math.min(Math.ceil(wanted.size * 0.7), 8);
  if (hits.size < required) {
    throw new Error(`${where} - uses ${hits.size} of the user's ingredients, needs at least ${required}`);
  }
  if (missing.length > 3) throw new Error(`${where} - ${missing.length} missing ingredients, at most 3 allowed`);

  if (!Array.isArray(rec.steps) || rec.steps.length < 2) throw new Error(`${where} - needs at least 2 steps`);
  const steps = rec.steps.map((s, i) => {
    const assignedTo = Number(s.assignedTo ?? 1);
    if (!(assignedTo >= 1 && assignedTo <= r.helpers)) throw new Error(`${where} - step ${i+1} assigned to cook ${assignedTo}, only ${r.helpers} cooking`);
    if (typeof s.text !== 'string' || !s.text.trim()) throw new Error(`${where} - step ${i+1} has no text`);
    if (typeof s.title !== 'string' || !s.title.trim()) throw new Error(`${where} - step ${i+1} has no title`);
    return { number: i + 1, title: s.title.trim(), text: s.text.trim(), parallel: Boolean(s.parallel), assignedTo };
  });

  const n = rec.nutrition || {};
  const num = (v, f) => { const x = Number(v); if (!(x >= 0)) throw new Error(`${where} - bad nutrition ${f}`); return x; };
  // Portion weight (in grams) is stored for n8n's own records even though
  // the frontend no longer displays it (it briefly fed a per-100g nutrition
  // display, reverted 2026-10-01 to match User Story 10's "per portion"
  // wording) - unlike the other nutrition fields it must be a positive
  // integer, and missing/invalid values are rejected outright rather than
  // silently defaulted.
  const portionWeightG = Number(n.portionWeightG);
  if (!Number.isInteger(portionWeightG) || portionWeightG <= 0) {
    throw new Error(`${where} - missing or invalid portionWeightG`);
  }
  const nutrition = {
    caloriesPerPortion: num(n.caloriesPerPortion, 'caloriesPerPortion'),
    proteinG: num(n.proteinG, 'proteinG'),
    carbsG: num(n.carbsG, 'carbsG'),
    fatG: num(n.fatG, 'fatG'),
    portionWeightG,
  };
  if (!(nutrition.caloriesPerPortion > 0)) throw new Error(`${where} - calories must be positive`);

  // US9: with more than one cook, each needs one fixed, named area of the
  // dish - responsibilities is what the UI shows above the steps ("Chef 1:
  // pasta · Chef 2: sauce"). Checked structurally only (right length,
  // non-empty labels); whether a cook's steps genuinely stay one coherent
  // area is down to the prompt, not something code can verify.
  const responsibilities = Array.isArray(rec.responsibilities)
    ? rec.responsibilities.map((s) => (typeof s === 'string' ? s.trim() : ''))
    : [];
  if (responsibilities.length !== r.helpers || responsibilities.some((s) => !s)) {
    throw new Error(`${where} - responsibilities must have ${r.helpers} non-empty label(s), got ${JSON.stringify(rec.responsibilities)}`);
  }

  return { json: {
    createdAt, title: rec.title.trim(), cuisine: r.cuisine, diet: r.diet,
    timeCategory: r.cookingTime, cookingTimeMinutes: minutes,
    portions: r.portions, helpers: r.helpers,
    ingredientsUsed: used, ingredientsMissing: missing, steps, nutrition, responsibilities,
  } };
});

// Collects the Firebase keys of the three writes and raises the counters.
// Firebase POST answers with {"name": "<generated key>"} - that key is the
// recipe id the frontend uses in /recipe/:id.
const writes = $input.all();
const ids = writes.map(w => w.json?.body?.name).filter(Boolean);
if (ids.length !== 3) throw new Error(`Expected 3 Firebase keys, got ${ids.length}`);

const q = $('Check quota').first().json;
const counters = {};
counters[q.ipKey] = Number(q.used) + 1;
counters._total = Number(q.total) + 1;

return [{ json: { ids, date: q.date, counters,
                  remaining: Math.max(0, q.remaining - 1), limit: q.limit } }];

// Final answer: the three stored recipes plus the caller's remaining quota, so
// the generator can show the new count without a second request.
const meta = $('Collect ids and raise counters').first().json;
const recipes = $('Parse and verify recipes').all().map((item, i) => ({
  id: meta.ids[i], ...item.json,
}));
return [{ json: { recipes, quota: {
  remaining: meta.remaining, limit: meta.limit, systemLimitReached: false,
} } }];
